<template>
  <section aria-label="SOFA变化与感染独立复核">
    <p>变化复核分别绑定当前日、原基线与实际感染原件。未知基线保留范围；条件性零基线须明确核实两个前提，不能从缺少历史资料自动补零。</p>
    <el-form-item label="待计算SOFA变化评估"><el-select :disabled="locked||disabled" v-model="selectedId" aria-label="待计算SOFA变化评估" clearable placeholder="明确选择并重核原来源"><el-option v-for="row in items" :key="row.change_assessment_id" :value="row.change_assessment_id" :label="`${row.evaluation_at} · ${row.change_assessment_id}`" :disabled="row.status!=='active'||row.eligible===false" /></el-select></el-form-item>
    <el-button :disabled="disabled" :loading="loading" @click="refreshDirectory">刷新SOFA变化评估目录</el-button><el-pagination v-if="total>50" v-model:current-page="page" :page-size="50" :total="total" layout="prev,pager,next" @current-change="load" />
    <p v-if="error" role="alert">{{ error }}</p><p v-if="notice">{{ notice }}</p>
    <template v-if="selected"><p class="hash">已核对变化评估 {{ selected.change_assessment_id }} · {{ selected.content_hash }}。</p><template v-if="!locked&&!disabled&&selected.can_revoke===true"><el-input v-model="revokeReason" aria-label="SOFA变化撤销依据" maxlength="1000" /><el-button type="danger" :disabled="revoking||!revokeReason.trim()" @click="revoke">撤销所选SOFA变化评估</el-button></template></template>
    <p v-if="!locked&&!currentAssessment">登记新变化复核前，请明确选择并核对上方当前日评估。</p>
    <template v-else-if="!locked&&currentAssessment">
      <p>已明确当前日 {{ currentAssessment.period_start }} 至 {{ currentAssessment.period_end }}；资料截止 {{ currentAssessment.as_of }}。</p>
      <el-button :disabled="disabled" :loading="preflighting" @click="preflight">读取独立基线与感染候选</el-button>
      <el-form v-if="candidate" label-position="top" :disabled="creating||disabled||locked" @submit.prevent>
        <p v-if="candidate.can_sign!==true">服务端未确认当前实际医生和原住院签署资格。</p>
        <el-form-item label="SOFA原基线策略"><el-select v-model="baselineMode" aria-label="SOFA原基线策略" placeholder="必须明确选择，不把缺失默认为零"><el-option label="独立授权的真实24小时基线" value="observed" /><el-option label="医生明确核实的条件性零假设" value="conditional_zero" /><el-option label="基线未知，保留0至24范围" value="unknown" /></el-select></el-form-item>
        <template v-if="baselineMode==='observed'">
          <el-form-item label="SOFA独立原住院基线"><el-select v-model="baselineId" aria-label="SOFA独立原住院基线" placeholder="明确选择原住院与原日评估"><el-option v-for="row in candidate.baseline_assessments" :key="row.assessment_id" :value="row.assessment_id" :label="`${row.period_start} 至 ${row.period_end} · 原住院 ${row.admission_id} · ${row.assessment_id}`" /></el-select></el-form-item>
          <p v-if="baselineChecking">正在单独授权并核对真实基线原住院与全部原件。</p><p v-if="baseline">原基线已核对 {{ baseline.assessment_id }}；未把原住院改绑为当前住院。</p>
        </template>
        <template v-else-if="baselineMode==='conditional_zero'||baselineMode==='unknown'"><p v-if="baselineMode==='conditional_zero'">采用假设零基线前，需确认下方两个前提。</p><review-fields v-model="baselineReview" model-name="ChangeCreate" :definition="baselineMode==='conditional_zero'?'ConditionalZeroBaseline':'UnknownBaseline'" prefix="SOFA基线" /></template>
        <el-form-item label="SOFA原感染声明"><el-select v-model="infectionId" aria-label="SOFA原感染声明" placeholder="明确选择本次原住院实际感染原件"><el-option v-for="row in candidate.infection_sources" :key="row.support_source_id" :value="row.support_source_id" :label="`${row.recorded_at} · ${row.payload.infection_status} · ${row.support_source_id}`" /></el-select></el-form-item>
        <template v-if="infection"><p>原感染状态 {{ infection.payload.infection_status }}；原发作 {{ infection.payload.onset_at??'未知，不能由新判读补造' }}；原系统登记 {{ infection.recorded_at }}。</p><p v-if="infection.recorded_at>currentAssessment.as_of">感染声明登记晚于当日资料截止时间，本次采用当前回顾记录。</p><details><summary>院内核对原感染依据</summary><p>{{ infection.payload.infection_basis_note }}</p><p>{{ infection.payload.onset_basis_note }}</p></details></template>
        <review-fields v-model="infectionReview" model-name="ChangeCreate" definition="InfectionReview" prefix="SOFA感染" />
        <review-fields v-model="changeReview" model-name="ChangeCreate" definition="ChangeReview" prefix="SOFA变化" />
        <el-form-item label="SOFA变化复核备注"><el-input v-model="note" aria-label="SOFA变化复核备注" type="textarea" maxlength="1000" /></el-form-item>
        <p v-if="draftError" role="alert">{{ draftError }}</p><el-button type="primary" :disabled="!canCreate" :loading="creating" @click="create">仅登记SOFA当前回顾变化复核</el-button>
      </el-form>
    </template>
  </section>
</template>
<script setup>
import {computed,onActivated,onBeforeUnmount,onDeactivated,ref,watch} from "vue";
import {useStore} from "vuex";
import {createSofaChangeAssessment,getSofaAssessment,getSofaChangeAssessment,getSofaChangeAssessments,getSofaChangeCandidates,revokeSofaChangeAssessment,sofaChangeRequestValid,sofaRevocationMatches,verifySofaAssessment,verifySofaChangeAssessment} from "@/api/aiSofa";
import {supportCanonical,supportHash,supportId,verifySupportSource} from "@/api/inpatientSupport";
import ReviewFields from "./ReviewFields.vue";
const props=defineProps({patientId:{type:Number,required:true},admissionId:{type:String,default:""},currentAssessment:{type:Object,default:null},initialChangeAssessmentId:{type:String,default:""},active:{type:Boolean,default:true},locked:{type:Boolean,default:false},disabled:{type:Boolean,default:false}}),emit=defineEmits(["selection","availability","assessment-created"]);
const store=useStore(),roles=computed(()=>store.getters["user/permissions"]||[]),allowed=computed(()=>!!store.state.user.accessToken&&roles.value.some(role=>["nurse","doctor","director","admin","super_admin"].includes(role)));
const items=ref([]),total=ref(0),page=ref(1),selectedId=ref(""),selected=ref(null),loading=ref(false),error=ref(""),notice=ref(""),candidate=ref(null),preflighting=ref(false),baselineMode=ref(""),baselineId=ref(""),baseline=ref(null),baselineChecking=ref(false),baselineReview=ref({}),infectionId=ref(""),infectionReview=ref({}),changeReview=ref({}),note=ref(""),draftError=ref(""),creating=ref(false),revokeReason=ref(""),revoking=ref(false);
let epoch=0,listSeq=0,detailSeq=0,preflightSeq=0,baselineSeq=0,createSeq=0,alive=true,paused=false,initialAllowed=true;
const identity=()=>supportCanonical([props.patientId,props.admissionId,store.state.user.accessToken,roles.value,props.currentAssessment?.assessment_id,props.currentAssessment?.content_hash,props.currentAssessment?.projection_hash]),capture=()=>({epoch,identity:identity()}),current=ticket=>alive&&!paused&&props.active&&allowed.value&&ticket.epoch===epoch&&ticket.identity===identity();
const infection=computed(()=>candidate.value?.infection_sources.find(row=>row.support_source_id===infectionId.value));
function clearSelection(){detailSeq++;selected.value=null;revoking.value=false;revokeReason.value="";emit("selection",null);emit("availability",false);}
function clearDraft(){preflightSeq++;baselineSeq++;createSeq++;candidate.value=null;preflighting.value=baselineChecking.value=creating.value=false;baselineMode.value=baselineId.value=infectionId.value=note.value="";baseline.value=null;baselineReview.value={};infectionReview.value={};changeReview.value={};draftError.value="";}
function reset(){epoch++;listSeq++;clearSelection();clearDraft();selectedId.value="";items.value=[];total.value=0;page.value=1;loading.value=false;error.value=notice.value="";}
function refreshDirectory(){if(props.disabled)return;if(props.locked)initialAllowed=true;load();}
async function load(){const ticket=capture(),seq=++listSeq,requestedPage=page.value;clearSelection();selectedId.value="";items.value=[];if(!current(ticket)||!props.admissionId)return;loading.value=true;try{const response=await getSofaChangeAssessments({patient_id:props.patientId,admission_id:props.admissionId,page:requestedPage,page_size:50}),data=response.data;if(!current(ticket)||seq!==listSeq||requestedPage!==page.value)return;if(!Array.isArray(data?.items)||!Number.isSafeInteger(data.total)||data.items.some(row=>row.patient_id!==props.patientId||row.admission_id!==props.admissionId||!supportId(row.change_assessment_id)))throw new Error("SOFA变化目录与实际原住院不一致");items.value=data.items;total.value=data.total;if(initialAllowed&&props.initialChangeAssessmentId){initialAllowed=false;selectedId.value=props.initialChangeAssessmentId;}}catch(failure){if(current(ticket)&&seq===listSeq)error.value=failure?.message||"SOFA变化目录读取失败";}finally{if(current(ticket)&&seq===listSeq)loading.value=false;}}
async function preflight(){clearDraft();const ticket=capture(),seq=preflightSeq,row=props.currentAssessment;if(props.locked||props.disabled||!current(ticket)||!row)return;preflighting.value=true;try{const response=await getSofaChangeCandidates({patient_id:props.patientId,admission_id:props.admissionId,current_assessment_id:row.assessment_id,expected_current_content_hash:row.content_hash,expected_current_projection_hash:row.projection_hash}),data=response.data;if(!current(ticket)||seq!==preflightSeq)return;if(typeof data?.can_sign!=="boolean"||!await verifySofaAssessment(data.current_assessment,props.patientId,props.admissionId)||data.current_assessment.assessment_id!==row.assessment_id||data.current_assessment.content_hash!==row.content_hash||data.current_assessment.projection_hash!==row.projection_hash||!Array.isArray(data.baseline_assessments)||data.baseline_assessments.some(item=>item.patient_id!==props.patientId||!supportId(item.admission_id)||!supportId(item.assessment_id)||!supportHash(item.content_hash)||!supportHash(item.projection_hash)||item.period_end>row.period_start||item.as_of>row.as_of)||!Array.isArray(data.infection_sources)||!(await Promise.all(data.infection_sources.map(item=>verifySupportSource(item,"infection_episode",props.patientId,props.admissionId,true)))).every(Boolean))throw new Error("SOFA变化候选、独立基线或原感染来源未能完整核对");if(current(ticket)&&seq===preflightSeq)candidate.value=data;}catch(failure){if(current(ticket)&&seq===preflightSeq)draftError.value=failure?.message||"SOFA变化候选读取失败";}finally{if(current(ticket)&&seq===preflightSeq)preflighting.value=false;}}
function payload(){const row=props.currentAssessment;return{patient_id:props.patientId,admission_id:props.admissionId,current_assessment_id:row?.assessment_id,expected_current_content_hash:row?.content_hash,expected_current_projection_hash:row?.projection_hash,baseline:baselineMode.value==="observed"?{mode:"observed",assessment_id:baseline.value?.assessment_id,expected_content_hash:baseline.value?.content_hash,expected_projection_hash:baseline.value?.projection_hash}:{mode:baselineMode.value,...baselineReview.value},infection_source_id:infection.value?.support_source_id,expected_infection_content_hash:infection.value?.content_hash,expected_infection_governance_hash:infection.value?.governance_hash,infection_review:infectionReview.value,review:changeReview.value,note:note.value};}
const canCreate=computed(()=>!props.locked&&!props.disabled&&candidate.value?.can_sign===true&&!creating.value&&current(capture())&&sofaChangeRequestValid(payload(),props.currentAssessment,baseline.value,infection.value));
async function create(){if(!canCreate.value)return;const ticket=capture(),seq=++createSeq,values=payload(),signature=supportCanonical(values);clearSelection();selectedId.value="";creating.value=true;draftError.value="";try{const response=await createSofaChangeAssessment(values),row=response.data;if(!current(ticket)||seq!==createSeq||signature!==supportCanonical(payload()))return;if(!await verifySofaChangeAssessment(row,props.patientId,props.admissionId)||row.current_assessment_id!==values.current_assessment_id||row.infection_source_id!==values.infection_source_id||supportCanonical(row.snapshot.attestation)!==supportCanonical(values))throw new Error("SOFA变化回执与明确原来源不一致");if(!current(ticket)||seq!==createSeq||signature!==supportCanonical(payload()))return;clearDraft();notice.value="SOFA当前回顾变化复核已登记；请明确选择并重核，尚未调用规则模型。";emit("assessment-created",row.change_assessment_id);await load();}catch(failure){if(current(ticket)&&seq===createSeq){clearDraft();draftError.value=failure?.message||"SOFA变化登记失败，请重新核对候选与原件";}}finally{if(current(ticket)&&seq===createSeq)creating.value=false;}}
async function revoke(){const original=selected.value;if(original?.can_revoke!==true||!revokeReason.value.trim()||revoking.value)return;const ticket=capture(),reason=revokeReason.value.trim();clearSelection();selectedId.value="";revoking.value=true;try{const response=await revokeSofaChangeAssessment(original.change_assessment_id,{patient_id:props.patientId,admission_id:props.admissionId,expected_revision:original.revision,reason});if(!current(ticket))return;if(!await sofaRevocationMatches(response.data,original,props.patientId,props.admissionId,true))throw new Error("SOFA变化撤销回执与原CAS版本不一致");if(current(ticket)){notice.value="SOFA变化原件已撤销，仅保留治理审计。";await load();}}catch(failure){if(current(ticket))error.value=failure?.message||"SOFA变化撤销失败";}finally{if(current(ticket))revoking.value=false;}}
watch(selectedId,async id=>{clearSelection();const ticket=capture(),seq=detailSeq;if(!id||!current(ticket))return;try{const response=await getSofaChangeAssessment(id,{patient_id:props.patientId,admission_id:props.admissionId}),row=response.data;if(!current(ticket)||seq!==detailSeq||id!==selectedId.value)return;if(!await verifySofaChangeAssessment(row,props.patientId,props.admissionId)||row.change_assessment_id!==id)throw new Error("SOFA变化原件或全部关联已失效，不能作为当前计算来源");if(!current(ticket)||seq!==detailSeq||id!==selectedId.value)return;selected.value=row;emit("selection",{sofa_change_assessment_id:id});emit("availability",true);}catch(failure){if(current(ticket)&&seq===detailSeq)error.value=failure?.message||"SOFA变化原件无法重新核对";}});
watch(baselineMode,()=>{baselineSeq++;baselineId.value="";baseline.value=null;baselineReview.value={};});
watch(baselineId,async id=>{baseline.value=null;baselineChecking.value=false;const ticket=capture(),seq=++baselineSeq,metadata=candidate.value?.baseline_assessments.find(row=>row.assessment_id===id);if(!id||!metadata||!current(ticket)||baselineMode.value!=="observed")return;baselineChecking.value=true;try{const response=await getSofaAssessment(id,{patient_id:props.patientId,admission_id:metadata.admission_id}),row=response.data;if(!current(ticket)||seq!==baselineSeq||baselineId.value!==id)return;if(!await verifySofaAssessment(row,props.patientId,metadata.admission_id)||row.assessment_id!==id||row.content_hash!==metadata.content_hash||row.projection_hash!==metadata.projection_hash)throw new Error("SOFA原基线完整来源、原住院授权或摘要不一致");if(current(ticket)&&seq===baselineSeq&&baselineId.value===id)baseline.value=row;}catch(failure){if(current(ticket)&&seq===baselineSeq)draftError.value=failure?.message||"独立原基线无法授权核对";}finally{if(current(ticket)&&seq===baselineSeq)baselineChecking.value=false;}});
watch([identity,()=>props.active,()=>props.initialChangeAssessmentId],(values,previous)=>{initialAllowed=!previous||values[2]!==previous[2];reset();load();},{immediate:true,flush:"sync"});onDeactivated(()=>{paused=true;initialAllowed=false;reset();});onActivated(()=>{if(paused){paused=false;reset();load();}});onBeforeUnmount(()=>{alive=false;reset();});
</script>
<style scoped>p{line-height:1.7}.hash{overflow-wrap:anywhere}.el-button{margin:8px 8px 8px 0}</style>
